// icons.js — 食材アイコンセット（同梱SVG）
//
// 方針:
// - 食材名からアイコンを引く（FOOD_ICONS のキーワード一致 → 個別アイコン）。
// - 一致しなければカテゴリ別の汎用アイコンにフォールバックする。
// - スタイルは、ユーザーが見本に挙げた絵本風イラストに寄せた
//   「細めで温かいブラウンの線＋淡いパステルの水彩風の色面」。
//   輪郭は細く柔らかく、塗りは彩度を落とした淡い色にそろえ、落影も
//   ごく薄くして、手描きの丸みが出るようにしている。
//   顔は全アイコンに付けるが、表情は食材ごとに変えて個性を出す
//   （にっこり／^^／ねむい／びっくり／舌ペロ／照れ…。詳細は EXPR）。
//   位置づけは「アイコン（ピクトグラム）」ではなく「キャラクター」:
//   食材の形そのものを丸みのある体として、表情＋体の傾き＋
//   食材の特徴をキャラの特徴に見立てる小物（葉っぱ＝髪/帽子、
//   ブロッコリーの房＝くるくる髪、卵の殻＝帽子、魚の泡、キラキラ等）で
//   個性を出す。ユーザーの指定により手足は付けない（「手足はなくていい」）。
//   傾き・小物・ツヤの割り当ては CHAR_ACC / GLOSS / HOP / TILT を参照。
//   仕上げ方針（「雑に見える」との指摘を受けて全93種を再構成）:
//   形は左右対称・重心中央を基本に、円/楕円/丸角矩形など整った形で描き、
//   葉脈・層線・種・網目などの細部は等間隔/対称に置く。線の太さと
//   角の丸みは全アイコンで統一し、顔の比率も共通ルールでそろえる。
//   背景は持たない（常に明るい地に載る）。
//   使い回し禁止（ユーザーの明示指示「同じイラストは使いまわさない」）:
//   図鑑カタログの全食材は、それぞれ専用のキャラクターを持つ。色だけ
//   変えたコピーも使い回しとみなし、形・模様・表情・小物まで描き分ける
//   （例：きのこ類は しいたけ=ひび割れ傘／えのき=細い束／しめじ=株束／
//   舞茸=フリル／エリンギ=太い軸／マッシュルーム=白い丸傘 で別キャラ）。
//   カテゴリ汎用キャラ（cat_*）は、カタログに無い未知・自由入力の
//   食材名だけに使う。
//   描き分け強化（「同じイラストが使われている／調味料はせめて色を
//   変えて／トマト缶をもっと表現して」との指摘を受けて）:
//   瓶もの調味料は同一シルエットをやめ、形（注ぎ口ディスペンサー／
//   細身／ずんぐり／広口ジャー等）＋液色＋ラベルのモチーフで判別。
//   汎用落ちしていた定番（めんつゆ・白だし・ドレッシング・
//   オイスターソース・焼肉のたれ・豆板醤・うどん・ジュース・大豆）
//   に専用キャラを追加。缶詰は缶の色＋ラベルに中身そのものを大きく
//   描く（トマト缶=赤缶に大きなトマト、サバ缶=青缶にさば、
//   コーン缶=黄缶にとうもろこしの芯、ツナ缶=開缶＋魚マーク帯）。
//   色違いコピーだった明太子／たらこ、ぶどう／シャインマスカットも
//   形から描き分け（たらこ=2つの房、シャインマスカット=縦長の粒）。
// - アイコンSVGはすべて静的な自前データで、食材名などのユーザー入力を
//   SVG文字列に混ぜることはない（XSS対策は従来通り）。
// - キャラ表示（iconEl）は、ミュゼ版のキャラ画像がある食材ではそちらを
//   採用する（ユーザー決定「野菜のキャラクターの絵などはミュゼ版を採用」。
//   解決ルールと使い回し禁止の扱いは js/chars.js の冒頭コメント参照）。
// - ユーザー方針「WEB版のイラストは不採用」: 食材キャラの表示にこのSVGは
//   使わない。ミュゼ版アートが無い食材は、絵なしの仮表示にする。

import { charUrlFor } from "./chars.js";
import { resolveCanonicalName } from "./names.js";

const STROKE = "#9e744a";
function svg(inner) {
  return `<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="${STROKE}" stroke-width="1.35" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><defs><filter id="ic-sh" x="-20%" y="-20%" width="140%" height="140%"><feDropShadow dx="0" dy="0.6" stdDeviation="0.45" flood-color="#c9ab7d" flood-opacity="0.2"/></filter></defs><g filter="url(#ic-sh)">${inner}</g></svg>`;
}

