// 表情ごとのほっぺの濃さ（opacity）。照れは濃く、ねむい・おだやかは薄く。
const CHEEK = { smile: 0.6, happy: 0.65, grin: 0.65, sleepy: 0.4, calm: 0.5, surprised: 0.5, playful: 0.65, shy: 0.95, wink: 0.6 };

function faceSvg(key, [x, y, s, r]) {
  const expr = EXPR[key] || "smile";
  const f = (v) => Math.round(v * 100) / 100;
  const dx = 2.3 * s, er = 0.8 * s;
  const eyeDot = (cx) => `<circle cx="${f(cx)}" cy="${y}" r="${f(er)}" fill="${STROKE}" stroke="none"/>`;
  const eyeArc = (cx, w, lift, drop) => `<path d="M${f(cx - w * s)} ${f(y + lift * s)}q${f(w * s)} ${f(drop * s)} ${f(2 * w * s)} 0" stroke-width="1.1"/>`;
  let eyes;
  if (expr === "happy" || expr === "grin") eyes = eyeArc(x - dx, 0.95, 0.3, -1.6) + eyeArc(x + dx, 0.95, 0.3, -1.6);
  else if (expr === "sleepy") eyes = eyeArc(x - dx, 0.85, -0.45, 1.8) + eyeArc(x + dx, 0.85, -0.45, 1.8);
  else if (expr === "calm") eyes = eyeArc(x - dx, 0.9, -0.05, 0.5) + eyeArc(x + dx, 0.9, -0.05, 0.5);
  else if (expr === "wink") eyes = eyeDot(x - dx) + eyeArc(x + dx, 0.9, -0.05, 0.5);
  else eyes = eyeDot(x - dx) + eyeDot(x + dx);
  const my = y + 1.35 * s;
  const smileArc = (w, h) => `<path d="M${f(x - w * s)} ${f(my)}q${f(w * s)} ${f(h * s)} ${f(2 * w * s)} 0" stroke-width="1.1"/>`;
  const openMouth = (w, h) => `<path d="M${f(x - w * s)} ${f(my - 0.1 * s)}q${f(w * s)} ${f(h * s)} ${f(2 * w * s)} 0q${f(-w * s)} ${f(-0.5 * s)} ${f(-2 * w * s)} 0Z" fill="${STROKE}" stroke="none"/>`;
  let mouth;
  if (expr === "happy") mouth = openMouth(1.0, 1.9);
  else if (expr === "grin") mouth = openMouth(1.3, 2.4) + `<ellipse cx="${x}" cy="${f(my + 1.0 * s)}" rx="${f(0.55 * s)}" ry="${f(0.32 * s)}" fill="#f4ac9c" stroke="none"/>`;
  else if (expr === "surprised") mouth = `<circle cx="${x}" cy="${f(my + 0.35 * s)}" r="${f(0.55 * s)}" fill="${STROKE}" stroke="none"/>`;
  else if (expr === "sleepy") mouth = `<ellipse cx="${x}" cy="${f(my + 0.5 * s)}" rx="${f(0.48 * s)}" ry="${f(0.62 * s)}" fill="${STROKE}" stroke="none" opacity="0.85"/>`;
  else if (expr === "playful") mouth = smileArc(1.05, 1.15) + `<ellipse cx="${f(x + 0.55 * s)}" cy="${f(my + 1.2 * s)}" rx="${f(0.48 * s)}" ry="${f(0.68 * s)}" fill="#f4ac9c" stroke="none"/>`;
  else if (expr === "shy") mouth = smileArc(0.6, 0.7);
  else if (expr === "calm") mouth = smileArc(1.0, 0.8);
  else mouth = smileArc(1.05, 1.15);
  const co = CHEEK[expr] ?? 0.6, cx = 3.9 * s, cy = 1.6 * s;
  const cheeks =
    `<ellipse cx="${f(x - cx)}" cy="${f(y + cy)}" rx="${f(1.25 * s)}" ry="${f(0.8 * s)}" fill="#f4ac9c" stroke="none" opacity="${co}"/>` +
    `<ellipse cx="${f(x + cx)}" cy="${f(y + cy)}" rx="${f(1.25 * s)}" ry="${f(0.8 * s)}" fill="#f4ac9c" stroke="none" opacity="${co}"/>`;
  const inner = eyes + cheeks + mouth;
  return r ? `<g transform="rotate(${r} ${x} ${y})">${inner}</g>` : inner;
}
for (const [k, pos] of Object.entries(FACE_POS)) {
  if (ICONS[k]) ICONS[k] = ICONS[k].replace("</svg>", faceSvg(k, pos) + "</svg>");
}

// ---------- キャラクター仕上げ（手足なし） ----------
// 「アイコンっていうよりキャッチーなキャラクターのイメージ」という声と、
// 「手足はなくていい」という指定を受けての仕上げ。キャラクター感は
// 次の3要素で出す（手足・ポーズは使わない）。
// 1) CHAR_ACC: 食材の特徴をキャラの特徴に見立てた小物・仕草。
//    葉っぱ＝髪/帽子、卵の割れた殻＝帽子、牛乳パックのストロー、
//    魚介の泡、あさりの真珠、湯気、ねぎの束バンド、チョコのハート刻印など。
//    顔や食材の判別ポイントに被らない位置にだけ置く。
// 2) GLOSS: 体の左上に小さなツヤを入れて、ぷっくり丸い体に見せる。
// 3) HOP / TILT: 元気な表情の子には両脇に小さなバウンス弧を添え、
//    全員に表情タイプに合わせた小さな傾き（±2〜5°）を付けて、
//    置物ではなく「生きているキャラ」の気配を出す。傾きはキーで固定。
