for (const k of Object.keys(ICONS)) {
  let extra = "";
  const g = GLOSS[k];
  if (g) extra += `<ellipse cx="${g[0]}" cy="${g[1]}" rx="${g[2]}" ry="${g[3]}" transform="rotate(${g[4]} ${g[0]} ${g[1]})" fill="#ffffff" stroke="none" opacity="0.38"/>`;
  if (CHAR_ACC[k]) extra += CHAR_ACC[k];
  if (HOP.has(k)) extra += HOP_SVG;
  if (extra) ICONS[k] = ICONS[k].replace("</svg>", extra + "</svg>");
  const t = TILT[k];
  if (t) ICONS[k] = ICONS[k].replace(/(<svg[^>]*>)/, `$1<g transform="rotate(${t} 12 12)">`).replace(/<\/svg>$/, "</g></svg>");
}

