/** 食材名 → "ultra"（激レア）/ "rare"（レア）/ null */
export function rarityOf(name) {
  const r = RARITY[String(name || "")];
  return r ? r.tier : null;
}
/** レア食材の登録用カテゴリ（図鑑セルの下書きに使う） */
export function rarityCategory(name) {
  const r = RARITY[String(name || "")];
  return r ? r.category : null;
}

/** 一般名・略称 → 正規のカタログ名（Task BE, 2026-11-14）。
 * 在庫に素の呼び名で登録された食材を、正規品として解決するための対応表。
 * chars.js の CHAR_ALIASES / knowledge.js の KNOWLEDGE_ALIASES と同じ集合。 */
export const NAME_ALIASES = {
  "ねぎ": "長ねぎ",
  "白ねぎ": "長ねぎ",
  "万能ねぎ": "小ねぎ",
  "アスパラ": "アスパラガス",
  "いんげん": "さやいんげん",
  "さやえんどう": "絹さや",
  "しそ": "大葉",
  "かいわれ": "かいわれ大根",
  "とうがん": "冬瓜",
  "ぎんなん": "銀杏",
};

/** 食材の実効カテゴリ（図鑑のカテゴリ別表示用）。
 * レア枠の食材は RARITY のカテゴリ、それ以外は所属グループのカテゴリ。
 * 一般名・略称は正規品のカテゴリに解決する。カタログ外の名前は null。 */
export function categoryOf(name) {
  // 表記ゆれ（ネギ・玉葱・たまご等）は正規名に解決してから引く（names.js）。
  const key = resolveCanonicalName(String(name || ""));
  if (RARITY[key]) return RARITY[key].category;
  for (const [, category, names] of CATALOG) if (names.includes(key)) return category;
  if (NAME_ALIASES[key]) return categoryOf(NAME_ALIASES[key]);
  return null;
}

/** カタログに登場するカテゴリの一覧（カタログ登場順）。 */
export function catalogCategories() {
  const out = [];
  for (const [, , names] of CATALOG) for (const n of names) {
    const c = categoryOf(n);
    if (c && !out.includes(c)) out.push(c);
  }
  return out;
}

