/**
 * 食材名（と任意でカテゴリ）からアイコンのキーを引く。
 * 優先順位: 個別キーワード > カテゴリ汎用 > 名前からの推定 > その他汎用
 */
export function iconKeyFor(name, category) {
  const n = String(name || "");
  // 一般名・略称は正規品のアイコンに完全一致で解決する（部分一致の誤爆防止）
  if (NAME_ALIASES[n]) return iconKeyFor(NAME_ALIASES[n], category);
  const canonName = resolveCanonicalName(n);
  if (canonName !== n) return iconKeyFor(canonName, category);
  for (const [words, key] of FOOD_KEYWORDS) {
    if (words.some((w) => n.includes(w))) return key;
  }
  if (category && CATEGORY_ICONS[category]) return CATEGORY_ICONS[category];
  for (const [words, key] of NAME_GROUPS) {
    if (words.some((w) => n.includes(w))) return key;
  }
  return "cat_generic";
}

/** アイコンのSVG文字列を返す（静的データのみ。ユーザー入力は混ざらない）。 */
export function iconSvg(name, category) {
  return ICONS[iconKeyFor(name, category)] || ICONS.cat_generic;
}

/** 仮表示（ミュゼ版キャラが無い食材用・絵のないプレースホルダー） */
export function charPlaceholderEl() {
  const ph = document.createElement("span");
  ph.className = "char-placeholder";
  ph.textContent = "？";
  return ph;
}

/**
 * DOM要素として食材キャラを返す（span.food-icon）。
 * ユーザー方針: 食材キャラの表示には Web版SVGイラストは使わない。
 * ミュゼ版キャラ画像がある食材はそれを表示し、無い食材は絵なしの
 * 仮表示（char-placeholder）にする。iconSvg() は表示には使わない
 * （SVGデータ自体は残すが、食材キャラの描画経路からは外してある）。
 */
export function iconEl(name, category) {
  const span = document.createElement("span");
  span.className = "food-icon";
  span.setAttribute("aria-hidden", "true");
  const url = charUrlFor(name);
  if (url) {
    const img = document.createElement("img");
    img.className = "char-img";
    img.src = url;
    img.alt = "";
    img.draggable = false;
    // 画像が読めなかった場合も SVG にはせず仮表示にする
    img.addEventListener("error", () => { span.replaceChildren(charPlaceholderEl()); }, { once: true });
    span.appendChild(img);
    return span;
  }
  span.appendChild(charPlaceholderEl());
  return span;
}
